(* [comment removed for export] *)
Lemma s_loopC : forall (fx : FPState) R M model K sp1 a0v a1v,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 (sp1 - 32) -> spok sp1 ->
  getr R 10%bv = Z_to_bv 64 a0v -> getr R 11%bv = Z_to_bv 64 a1v -> 0 <= a0v < 2 ^ 64 -> 0 <= a1v < 2 ^ 64 ->
  (a0v = a1v -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 32) -> getr R' 1%bv = Z_to_bv 64 RT.CD_R_CHUNK ->
      getr R' 10%bv = getr R 8%bv -> getr R' 11%bv = getr R 9%bv -> TK.keepsR KSA R R' -> srealizes RSEGS SCFG (@PML.cfg fx' R' PML.PC_READ_CHUNK M model) K) ->
  (a0v <> a1v -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 32) -> getr R' 1%bv = Z_to_bv 64 RT.CD_R_PCD ->
      getr R' 10%bv = getr R 18%bv -> getr R' 11%bv = getr R 9%bv -> TK.keepsR KSA R R' -> srealizes RSEGS SCFG (@PML.cfg fx' R' PML.PC_PCHECK_DONE M model) K) ->
  srealizes RSEGS SCFG (@PML.cfg fx R RT.LOOPC M model) K.
