(* [comment removed for export] *)
Lemma s_rn_entry : forall (fx : FPState) R M model K sp1 Rr IS rdb sb rav,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 sp1 -> spok sp1 ->
  getr R 10%bv = Z_to_bv 64 Rr -> getr R 1%bv = Z_to_bv 64 rav -> 0 <= rav < 2 ^ 64 -> pok Rr -> pok IS -> PML.img_ro M ->
  L5.u64_at RSEGS M (Rr + 240) IS -> L5.u64_at RSEGS M IS PML.VT_ISS -> L5.u8_at RSEGS M (IS + 152) rdb -> 0 <= rdb <= 255 -> Z.land rdb 1 = 0 ->
  L5.u64_at RSEGS M (Rr + 568) sb -> 0 <= sb < 2 ^ 64 -> L5.defined M (sp1 - 80) 80 -> L5.defined M (Rr + 576) 8 ->
  sp1 <= Rr -> sp1 <= IS -> (Rr + 584 <= IS \/ IS + 272 <= Rr + 576) ->
  (forall (fx' : FPState) R' M', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> getr R' 1%bv = Z_to_bv 64 RT.RN_R_PUSH ->
      getr R' 10%bv = Z_to_bv 64 (Rr + 568) -> getr R' 11%bv = Z_to_bv 64 (sp1 - 65) ->
      getr R' 8%bv = getr R 11%bv -> getr R' 9%bv = Z_to_bv 64 Rr -> getr R' 18%bv = Z_to_bv 64 (Rr + 320) -> TK.keepsR KS012 R R' ->
      rn_frame M' sp1 rav R ->
      L5.u8_at RSEGS M' (sp1 - 65) 0 -> L5.u64_at RSEGS M' (Rr + 576) sb ->
      TK.samem (fun a => ~ (sp1 - 80 <= a < sp1) /\ ~ (Rr + 576 <= a < Rr + 584)) M M' -> mem_grows M M' ->
