(* [comment removed for export] *)
Lemma s_rn_r_chunkA : forall (fx : FPState) R M model K sp1 Rr Ev code vis p e p' k,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 (sp1 - 80) -> spok sp1 ->
  getr R 9%bv = Z_to_bv 64 Rr -> getr R 8%bv = Z_to_bv 64 Ev -> pok Rr -> pok Ev -> getr R 10%bv = Z_to_bv 64 p' -> getr R 11%bv = Z_to_bv 64 k -> 0 <= p' -> 0 <= k -> p' + k < 2 ^ 64 ->
  L5.u32_at RSEGS M Ev code -> 0 <= code < 2 ^ 31 -> L5.u64_at RSEGS M (Rr + 312) vis -> L5.u64_at RSEGS M (Rr + 512) e -> L5.u64_at RSEGS M (Rr + 520) p ->
  0 <= vis < 2 ^ 64 -> 0 <= p < 2 ^ 64 -> 0 <= e < 2 ^ 64 -> L5.defined M (Rr + 512) 16 -> (Rr + 592 <= Ev \/ Ev + 16 <= Rr) ->
  (code <> 0 -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> TK.keepsR KSW R R' ->
      srealizes RSEGS SCFG (@PML.cfg fx' R' RT.RN_EPI M model) K) ->
  (code = 0 -> forall (fx' : FPState) R' M' pn en, PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> getr R' 1%bv = Z_to_bv 64 RT.RN_R_PSOME ->
      getr R' 10%bv = getr R 18%bv -> getr R' 11%bv = Z_to_bv 64 vis -> getr R' 12%bv = Z_to_bv 64 Ev -> getr R' 19%bv = Z_to_bv 64 pn -> getr R' 22%bv = Z_to_bv 64 en -> TK.keepsR KSW R R' ->
      ((k = 0 /\ pn = p /\ en = e /\ M' = M) \/
       (k <> 0 /\ pn = p' /\ en = p' + k /\ L5.u64_at RSEGS M' (Rr + 512) en /\ L5.u64_at RSEGS M' (Rr + 520) pn /\ TK.samem (fun a => ~ (Rr + 512 <= a < Rr + 528)) M M' /\ mem_grows M M')) ->
