(* [comment removed for export] *)
Lemma s_rn_r_ws2 : forall (fx : FPState) R M model K sp1 Rr p e,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 (sp1 - 80) -> spok sp1 ->
  getr R 9%bv = Z_to_bv 64 Rr -> pok Rr -> L5.u64_at RSEGS M (Rr + 512) e -> L5.u64_at RSEGS M (Rr + 520) p -> 0 <= p < 2 ^ 64 -> 0 <= e < 2 ^ 64 ->
  (p = e -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> getr R' 1%bv = Z_to_bv 64 RT.RN_R_CHUNKB ->
      getr R' 10%bv = Z_to_bv 64 Rr -> getr R' 11%bv = getr R 8%bv -> TK.keepsR KSA R R' -> srealizes RSEGS SCFG (@PML.cfg fx' R' PML.PC_READ_CHUNK M model) K) ->
  (p <> e -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> TK.keepsR KSA R R' ->
