(* [comment removed for export] *)
Lemma s_rn_r_chunkB : forall (fx : FPState) R M model K sp1 Rr Ev code p e p' k,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 (sp1 - 80) -> spok sp1 ->
  getr R 9%bv = Z_to_bv 64 Rr -> getr R 8%bv = Z_to_bv 64 Ev -> pok Rr -> pok Ev -> getr R 10%bv = Z_to_bv 64 p' -> getr R 11%bv = Z_to_bv 64 k -> 0 <= p' -> 0 <= k -> p' + k < 2 ^ 64 ->
  L5.u32_at RSEGS M Ev code -> 0 <= code < 2 ^ 31 -> L5.u64_at RSEGS M (Rr + 512) e -> L5.u64_at RSEGS M (Rr + 520) p -> 0 <= p < 2 ^ 64 -> 0 <= e < 2 ^ 64 ->
  L5.defined M (Rr + 512) 16 -> (Rr + 592 <= Ev \/ Ev + 16 <= Rr) ->
  (code <> 0 -> forall (fx' : FPState) R', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> TK.keepsR KSA R R' ->
      srealizes RSEGS SCFG (@PML.cfg fx' R' RT.RN_EPI M model) K) ->
  (code = 0 -> forall (fx' : FPState) R' M', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp1 - 80) -> TK.keepsR KSA R R' ->
      ((k = 0 /\ M' = M) \/
       (k <> 0 /\ L5.u64_at RSEGS M' (Rr + 512) (p' + k) /\ L5.u64_at RSEGS M' (Rr + 520) p' /\ TK.samem (fun a => ~ (Rr + 512 <= a < Rr + 528)) M M' /\ mem_grows M M')) ->
