Lemma s_cd_r_pcd : forall (fx : FPState) R M model K sp1 Rr Ev code p e,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx -> getr R 2%bv = Z_to_bv 64 (sp1 - 32) -> spok sp1 ->
  getr R 8%bv = Z_to_bv 64 Rr -> getr R 9%bv = Z_to_bv 64 Ev -> pok Rr -> pok Ev ->
